# Check Product class exists
if 'Product' not in globals():
    raise AssertionError('Step 1: Product class not defined')

Product = globals()['Product']

# Check it's actually a class
if not isinstance(Product, type):
    raise AssertionError('Step 1: Product should be a class')

# Check __init__ exists and has correct parameters by testing instantiation
try:
    # Should work with default in_stock
    test1 = Product('Test', 10.0)
    if test1.in_stock != True:
        raise AssertionError('Step 2: in_stock should default to True')
except TypeError as e:
    if 'missing' in str(e) or 'required' in str(e):
        raise AssertionError('Step 2: __init__ should have default value for in_stock')
    raise AssertionError(f'Step 2: Error creating Product: {e}')

# Should work with explicit in_stock
try:
    test2 = Product('Test', 10.0, False)
    if test2.in_stock != False:
        raise AssertionError('Step 2: in_stock should accept explicit False value')
except Exception as e:
    raise AssertionError(f'Step 2: Error creating Product with explicit in_stock: {e}')

print('TEST_PASSED')

# Check for required variables
required_vars = ['book', 'software']
for var in required_vars:
    if var not in globals():
        raise AssertionError(f'Step 4: Variable "{var}" not found')

# Check they are Product instances
