book = globals()['book']
software = globals()['software']

if not isinstance(book, Product):
    raise AssertionError('Step 4: book should be an instance of Product')
if not isinstance(software, Product):
    raise AssertionError('Step 4: software should be an instance of Product')

# Check book attributes
if not hasattr(book, 'name') or book.name != 'Python Guide':
    raise AssertionError('Step 3 & 4: book.name should be "Python Guide"')
if not hasattr(book, 'price') or abs(book.price - 49.99) > 0.01:
    raise AssertionError('Step 3 & 4: book.price should be 49.99')
if not hasattr(book, 'in_stock') or book.in_stock != True:
    raise AssertionError('Step 3 & 4: book.in_stock should be True (default)')

# Check software attributes
if not hasattr(software, 'name') or software.name != 'PyCharm License':
    raise AssertionError('Step 3 & 4: software.name should be "PyCharm License"')
if not hasattr(software, 'price') or abs(software.price - 199.99) > 0.01:
    raise AssertionError('Step 3 & 4: software.price should be 199.99')
if not hasattr(software, 'in_stock') or software.in_stock != False:
    raise AssertionError('Step 3 & 4: software.in_stock should be False')

